function findMedianSortedArrays(nums1: number[], nums2: number[]): number {
  // Бинарный поиск ведём по более короткому массиву
  if (nums1.length > nums2.length) return findMedianSortedArrays(nums2, nums1);

  const m = nums1.length;
  const n = nums2.length;
  // Размер левой половины объединённого массива (при нечётной сумме — на 1 больше)
  const half = (m + n + 1) >> 1;

  // i — сколько элементов nums1 попадает в левую половину (от 0 до m)
  let lo = 0;
  let hi = m;

  while (lo <= hi) {
    const i = (lo + hi) >> 1;
    // Остальные элементы левой половины берём из nums2
    const j = half - i;

    // Соседи по линии разреза; за границами массива — ±бесконечность
    const left1 = i > 0 ? nums1[i - 1] : -Infinity;
    const right1 = i < m ? nums1[i] : Infinity;
    const left2 = j > 0 ? nums2[j - 1] : -Infinity;
    const right2 = j < n ? nums2[j] : Infinity;

    if (left1 <= right2 && left2 <= right1) {
      // Разрез правильный: всё слева <= всего справа
      const maxLeft = Math.max(left1, left2);
      if ((m + n) % 2 === 1) return maxLeft;
      const minRight = Math.min(right1, right2);
      return (maxLeft + minRight) / 2;
    }

    if (left1 > right2) {
      // Взяли из nums1 слишком много — сдвигаем разрез влево
      hi = i - 1;
    } else {
      // Взяли из nums1 слишком мало — сдвигаем разрез вправо
      lo = i + 1;
    }
  }

  // Для отсортированных массивов сюда не попадаем
  return 0;
}

// Время: O(log(min(m, n)))
// Память: O(1)
